<main class="panel"><h1>Servers</h1><p><a href="/servers/builds">Build servers</a></p><p><a class="wz-ok" href="/servers/create">Create at a provider</a> <a class="wz-ok" href="/servers/connect">Connect an existing server</a></p>
<?php if (isset($_SESSION['app_draft'])): ?><p><a href="/apps/create">Continue app setup</a></p><?php endif ?>
<?php $this->servers->_display('pending', $viewData); ?>
<?php $monitor = new Monitoring_model('monitoring'); foreach ($inventory['servers'] as $server): ?><section class="card"><h2><?= $e($server['id']) ?></h2><p><?= $e($server['host']) ?> / <?= !empty($server['builder_ready']) ? 'Ready for builds' : ($server['application_ready'] ? 'Ready for apps' : 'Runtime preparation required') ?></p><p><?= !empty($server['local_builder_ready']) ? 'Local builds enabled' : '' ?></p><?php $capacity = $monitor->_summary($server['id']); $sample = $capacity['latest']; ?><?php if ($sample): ?><h3>Capacity</h3><p><?= $capacity['stale'] ? 'Last known readings (monitoring is stale)' : 'Updated ' . $e(date('H:i', $sample['at'])) ?></p><dl><dt>CPU usage</dt><dd><?= $sample['cpu_percent'] === null ? 'Unavailable' : $e($sample['cpu_percent']) . '%' ?></dd><dt>Memory used</dt><dd><?= $e(round($sample['memory_used'] / 1073741824, 1)) ?> / <?= $e(round($sample['memory_total'] / 1073741824, 1)) ?> GB</dd><dt>Disk used</dt><dd><?= $e(round($sample['disk_used'] / 1073741824, 1)) ?> / <?= $e(round($sample['disk_total'] / 1073741824, 1)) ?> GB</dd></dl><?php foreach ($capacity['hints'] as $hint): ?><p class="wz-help"><?= $e($hint) ?></p><?php endforeach ?><?php else: ?><p>Waiting for the first monitoring sample.</p><?php endif ?><p class="wz-hint">Scaling suggestions only. Automatic resizing is off; any future cost increase requires your opt-in.</p><?php if (!$server['application_ready'] && empty($server['builder_ready'])): ?><p>Missing: <?= $e(implode(', ', $server['missing'] ?? [])) ?></p><?php endif ?><form method="post" action="/servers/action"><?= $csrf() ?><input type="hidden" name="command" value="inspect-connected-server"><input type="hidden" name="server" value="<?= $e($server['id']) ?>"><button class="link-button">Refresh capabilities</button></form></section><?php endforeach ?>
<?php if (isset($_SESSION['server_operation'])): ?><p><a href="/servers/provision">View server creation progress</a></p><?php endif ?></main>
